"""sklearn.utils.class_weight — class-imbalance helpers."""

import numpy as _np


def compute_class_weight(class_weight, *, classes, y):
    """Inverse-frequency class weights for unbalanced classification."""
    y = _np.asarray(y); classes = _np.asarray(classes)
    if class_weight is None:
        return _np.ones(len(classes))
    if class_weight == 'balanced':
        counts = _np.array([(y == c).sum() for c in classes], dtype=float)
        return len(y) / (len(classes) * _np.maximum(counts, 1))
    if isinstance(class_weight, dict):
        return _np.array([class_weight.get(c, 1.0) for c in classes])
    return _np.ones(len(classes))


def compute_sample_weight(class_weight, y, *, indices=None):
    """Per-sample weights, derived from class weights."""
    y = _np.asarray(y)
    if class_weight is None:
        return _np.ones(len(y))
    classes = _np.unique(y)
    cw = compute_class_weight(class_weight, classes=classes, y=y)
    weight_map = dict(zip(classes, cw))
    sw = _np.array([weight_map.get(yi, 1.0) for yi in y])
    return sw if indices is None else sw[indices]
